function setLighting(){lotusRoomLight.visible=current==='lotusinside';const internal=['hall','stage'].includes(current),evening=lightSelect.value==='evening';light.intensity=internal?.1:evening?.1:1.1;hemi.intensity=internal?.23:evening?.23:.5;ambient.intensity=current==='lotusinside'?.45:internal?.17:.16;interiorLights.visible=internal;interiorLights.children.forEach(l=>l.intensity=.3);hallKey.visible=internal;eveningLights.visible=evening&&!internal;renderer.toneMappingExposure=internal?.8:evening?1:.85;scene.background=evening&&!internal?new THREE.Color('#152735'):null;mats.light.emissiveIntensity=evening?1.8:.6;mats.lotusGlass.emissiveIntensity=evening?.65:0;mats.lotusFinial.emissiveIntensity=evening?2:.8;}
